import {test,before,after} from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,readFileSync,writeFileSync,mkdirSync,rmSync,symlinkSync,existsSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join,dirname} from 'node:path';
import {fileURLToPath} from 'node:url';
import {gunzipSync} from 'node:zlib';
import {fixedLocalGit} from '../fixed-local-git.mjs';
const root=fileURLToPath(new URL('../../../',import.meta.url));
const BASE='68b996a5641b69e6f21705a114a4524e407fe097',ANCHOR='e8d727e21867aabe1e9246b5a940e08ecd063f33';
// 冻结普通源码数据：只解压JSON写入私有Git；不执行归档代码，不依赖未发布parent对象。
const OVERLAY="";
let HEAD;
const CATALOG='config/verification-retirements/alertness-v1.json';
const EXTRA_CATALOG='config/verification-retirements/legacy-five-v1.json';
const EXTRA_OLD=[...['harness-module-constants','initiative-completion','initiative-queue','quota-exhausted-no-quarantine'].map(n=>`packages/brain/src/__tests__/${n}.test.js`),'tests/regression/relay-28e7c41a/OpsPanoramaCard.test.tsx'];
const OLD=['diagnosis','escalation','healing','levels','metrics'].map(n=>`tests/alertness/${n}.test.js`);
let api,home,sourceRoot,controlRoot;
const git=(where,...args)=>fixedLocalGit(where,args,{encoding:'utf8'}).trim();
const needApi=()=>assert.equal(typeof api?.collectVerificationRetirementCandidates,'function','显式退休候选API必须存在');
function commit(where){git(where,'add','--sparse','-A');git(where,'-c','user.name=retirement-fixture','-c','user.email=fixture@example.invalid','-c','commit.gpgsign=false','commit','-qm','fixture');return git(where,'rev-parse','HEAD');}
function source(){return {repo:'perfectuser21/cecelia',base_revision:BASE,head_revision:git(sourceRoot,'rev-parse','HEAD'),changed_files:fixedLocalGit(sourceRoot,['diff','--no-renames','--name-only','-z',BASE,'HEAD','--'],{encoding:'utf8'}).split('\0').filter(Boolean).map(path=>({path}))};}
function options(extra={}){return {source:source(),toolingRoot:controlRoot,toolingRevision:git(controlRoot,'rev-parse','HEAD'),purpose:'admission_only',...extra};}
function reset(){git(sourceRoot,'reset','--hard',HEAD);git(sourceRoot,'clean','-fd');}
before(async()=>{
 try{api=await import('../implementation-verification-retirements.mjs');}catch(error){if(error.code!=='ERR_MODULE_NOT_FOUND')throw error;}
 if(!api)return;
 home=mkdtempSync(join(tmpdir(),'verification-retirement-'));sourceRoot=join(home,'source');controlRoot=join(home,'control');
 fixedLocalGit(root,['clone','--shared','--no-checkout','--quiet',root,sourceRoot],{localClone:true});
 git(sourceRoot,'remote','set-url','origin','https://github.com/perfectuser21/cecelia.git');
 git(sourceRoot,'sparse-checkout','set','--no-cone','/packages/brain/vitest.config.js','/packages/brain/src/__tests__/alertness/','/tests/alertness/');
 git(sourceRoot,'checkout','--detach',ANCHOR);
 const overlay=JSON.parse(gunzipSync(Buffer.from(OVERLAY,'base64')));
 for(const[path,text]of Object.entries(overlay)){const file=join(sourceRoot,path);mkdirSync(dirname(file),{recursive:true});writeFileSync(file,text);}
 for(const path of OLD)rmSync(join(sourceRoot,path),{force:true});HEAD=commit(sourceRoot);
 mkdirSync(controlRoot);git(controlRoot,'init','-q');git(controlRoot,'remote','add','origin','https://github.com/perfectuser21/cecelia.git');
 mkdirSync(dirname(join(controlRoot,CATALOG)),{recursive:true});writeFileSync(join(controlRoot,CATALOG),readFileSync(join(root,CATALOG)));if(existsSync(join(root,EXTRA_CATALOG)))writeFileSync(join(controlRoot,EXTRA_CATALOG),readFileSync(join(root,EXTRA_CATALOG)));commit(controlRoot);
});
after(()=>{if(home)rmSync(home,{recursive:true,force:true});});
test('五个显式退休仅产生候选，保留11替代输入与三项审计限制',()=>{
 needApi();const proof=api.collectVerificationRetirementCandidates(sourceRoot,options());
 assert.equal(proof.kind,'explicit_verification_retirement');assert.equal(proof.purpose,'admission_only');
 assert.deepEqual(proof.rows.map(r=>r.path).sort(),[...OLD].sort());assert.equal(proof.limitations.length,3);
 for(const row of proof.rows){assert.equal(row.change,'D');assert.equal(row.head.absent,true);assert.equal(row.replacement_inputs.length,11);assert.equal(row.entry_verified,false);assert.equal(row.owner_verified,false);assert.equal(row.retirement_authorized,false);assert.ok(row.replacement_inputs.every(i=>i.selector_witness&&i.selected_candidate));}
 assert.equal(proof.execution_status,'not_evaluated');assert.equal(proof.coverage,'unknown');
 assert.deepEqual(api.verifyVerificationRetirementCandidates(sourceRoot,{...options(),proof}),proof);
});
test('用途main/release/recovery和伪造witness不能授权退休',()=>{
 needApi();for(const purpose of ['main_verification','main','release','recovery','admission_source_only',undefined])assert.throws(()=>api.collectVerificationRetirementCandidates(sourceRoot,options({purpose})),/ADMISSION_ONLY/);
 const proof=api.collectVerificationRetirementCandidates(sourceRoot,options());proof.rows[0].retirement_authorized=true;
 assert.throws(()=>api.verifyVerificationRetirementCandidates(sourceRoot,{...options(),proof}),/MISMATCH/);
});
test('candidate改写审计JSON不能自授资格，control catalog改字节或漂移也拒绝',()=>{
 needApi();const catalog=join(controlRoot,CATALOG),original=readFileSync(catalog),control=git(controlRoot,'rev-parse','HEAD');
 try{writeFileSync(catalog,Buffer.concat([original,Buffer.from('\n')]));assert.throws(()=>api.collectVerificationRetirementCandidates(sourceRoot,options()),/STATE|DIRTY/);commit(controlRoot);assert.throws(()=>api.collectVerificationRetirementCandidates(sourceRoot,options()),/CATALOG/);assert.throws(()=>api.collectVerificationRetirementCandidates(sourceRoot,options({toolingRevision:control})),/STATE|MISMATCH/);}finally{git(controlRoot,'reset','--hard',control);}
 const candidate=join(sourceRoot,CATALOG);mkdirSync(dirname(candidate),{recursive:true});writeFileSync(candidate,'{"approved":true}');commit(sourceRoot);
 try{const proof=api.collectVerificationRetirementCandidates(sourceRoot,options());assert.equal(proof.rows.length,5);assert.notEqual(proof.control.catalog_sha256,'approved');}finally{reset();}
});
test('非official68基线即使仍有五份旧测试也不能冒充审核过的旧字节',()=>{
 needApi();assert.throws(()=>api.collectVerificationRetirementCandidates(sourceRoot,options({source:{...source(),base_revision:git(sourceRoot,'rev-parse',BASE+'^')}})),/BASE/);
});
test('A/M/R伪删除、旧路径仍存在与symlink均拒绝',()=>{
 needApi();const old=OLD[0],file=join(sourceRoot,old);mkdirSync(dirname(file),{recursive:true});
 for(const kind of ['regular','symlink']){
  try{if(kind==='symlink')symlinkSync('/tmp/foreign-test',file);else writeFileSync(file,'export const changed=true;');commit(sourceRoot);assert.throws(()=>api.collectVerificationRetirementCandidates(sourceRoot,options()),/DELETION|ABSEN|REGULAR/);}finally{reset();mkdirSync(dirname(file),{recursive:true});}
 }
 const renamed='tests/alertness/renamed.test.js';writeFileSync(join(sourceRoot,renamed),fixedLocalGit(sourceRoot,['show',`${BASE}:${old}`]));commit(sourceRoot);
 try{assert.throws(()=>api.collectVerificationRetirementCandidates(sourceRoot,options()),/DELETION|RENAME/);}finally{reset();}
});
test('改head配置或任一replacement字节都必须重新审核',()=>{
 needApi();for(const path of ['packages/brain/vitest.config.js','packages/brain/src/__tests__/alertness/diagnosis.test.js']){
  const file=join(sourceRoot,path);try{writeFileSync(file,Buffer.concat([readFileSync(file),Buffer.from('\n// drift\n')]));commit(sourceRoot);assert.throws(()=>api.collectVerificationRetirementCandidates(sourceRoot,options()),/CONFIG|REPLACEMENT/);}finally{reset();}
 }
});
test('replacement symlink、dirty source与head漂移必须拒绝',()=>{
 needApi();const file=join(sourceRoot,'packages/brain/src/__tests__/alertness/diagnosis.test.js');
 try{rmSync(file);symlinkSync('/tmp/foreign-test',file);commit(sourceRoot);assert.throws(()=>api.collectVerificationRetirementCandidates(sourceRoot,options()),/REGULAR|REPLACEMENT/);}finally{reset();}
 const original=readFileSync(file);writeFileSync(file,Buffer.concat([original,Buffer.from('\n')]));try{assert.throws(()=>api.collectVerificationRetirementCandidates(sourceRoot,options()),/STATE|DIRTY/);}finally{reset();}
 assert.throws(()=>api.collectVerificationRetirementCandidates(sourceRoot,options({source:{...source(),head_revision:BASE}})),/STATE|MISMATCH/);
});
test('未知删除与路径逃逸不进入五条合同，delta伪造被拒绝',()=>{
 needApi();const original=source();for(const path of ['../tests/alertness/diagnosis.test.js','/tests/alertness/diagnosis.test.js','tests/alertness/./diagnosis.test.js'])assert.throws(()=>api.collectVerificationRetirementCandidates(sourceRoot,options({source:{...original,changed_files:[{path}]}})),/SOURCE|DELTA|PATH/);
 assert.throws(()=>api.collectVerificationRetirementCandidates(sourceRoot,options({source:{...original,changed_files:original.changed_files.filter(c=>c.path!==OLD[0])}})),/DELTA/);
});
test('其它有价值且被排除的真实测试删除不借五条退休合同取得资格',()=>{
 needApi();const path='packages/brain/src/__tests__/actions-dedup.test.js';
 try{git(sourceRoot,'update-index','--force-remove',path);commit(sourceRoot);const proof=api.collectVerificationRetirementCandidates(sourceRoot,options());assert.equal(proof.rows.length,5);assert.equal(proof.rows.some(row=>row.path===path),false);}finally{reset();}
});
test('控制目录的catalog symlink不是普通审核blob',()=>{
 needApi();const path=join(controlRoot,CATALOG),revision=git(controlRoot,'rev-parse','HEAD');
 try{rmSync(path);symlinkSync('/tmp/candidate-catalog',path);commit(controlRoot);assert.throws(()=>api.collectVerificationRetirementCandidates(sourceRoot,options()),/CATALOG.*REGULAR/);}finally{git(controlRoot,'reset','--hard',revision);}
});
const replacements=[...['diagnosis','escalation','healing','levels','metrics'].map(n=>`packages/brain/src/__tests__/alertness/${n}.test.js`),...['diagnosis','escalation','healing','metrics'].map(n=>`packages/brain/src/alertness/__tests__/${n}.test.js`),'packages/brain/src/__tests__/alertness-index-refactor.test.js','packages/brain/src/__tests__/alertness-recovery.test.js'];
for(const path of replacements)test(`固定11替代/支撑测试逐项字节漂移拒绝：${path}`,()=>{
 needApi();try{git(sourceRoot,'sparse-checkout','add','--no-cone','/'+path);const file=join(sourceRoot,path);writeFileSync(file,Buffer.concat([readFileSync(file),Buffer.from('\n// byte drift\n')]));commit(sourceRoot);assert.throws(()=>api.collectVerificationRetirementCandidates(sourceRoot,options()),/REPLACEMENT/);}finally{reset();}
});
function retireExtra(){for(const path of EXTRA_OLD)git(sourceRoot,'update-index','--force-remove',path);commit(sourceRoot);}
function withLaterBase(run){
 git(sourceRoot,'checkout','--detach',ANCHOR);writeFileSync(join(sourceRoot,'new-baseline-marker'),'new protected source baseline');const base=commit(sourceRoot);
 const head=git(sourceRoot,'-c','user.name=retirement-fixture','-c','user.email=fixture@example.invalid','commit-tree',HEAD+'^{tree}','-p',base,'-m','same reviewed retirement on later baseline');
 git(sourceRoot,'reset','--hard',head);
 const actual={...source(),base_revision:base,changed_files:fixedLocalGit(sourceRoot,['diff','--no-renames','--name-only','-z',base,head,'--'],{encoding:'utf8'}).split('\0').filter(Boolean).map(path=>({path}))};
 try{return run(actual);}finally{reset();}
}
test('实际CI基线前移后仍逐blob核准原68目录，保真实base与历史锚点分域',()=>{
 needApi();withLaterBase(actual=>{
  const proof=api.collectVerificationRetirementCandidates(sourceRoot,options({source:actual}));assert.equal(proof.rows.length,5);
  for(const row of proof.rows){assert.equal(row.base.revision,actual.base_revision);assert.equal(row.catalog_anchor_revision,BASE);assert.equal(row.base.config.revision,actual.base_revision);}
  assert.deepEqual(api.verifyVerificationRetirementCandidates(sourceRoot,{...options({source:actual}),proof}),proof);
 });
});
test('较晚基线的旧blob或完整config漂移不继承68审核资格',()=>{
 needApi();for(const path of [OLD[0],'packages/brain/vitest.config.js']){
  git(sourceRoot,'checkout','--detach',ANCHOR);git(sourceRoot,'sparse-checkout','add','--no-cone','/'+path);
  const file=join(sourceRoot,path);writeFileSync(file,Buffer.concat([readFileSync(file),Buffer.from('\n// baseline drift\n')]));const base=commit(sourceRoot);
  const head=git(sourceRoot,'-c','user.name=retirement-fixture','-c','user.email=fixture@example.invalid','commit-tree',HEAD+'^{tree}','-p',base,'-m','candidate cannot erase baseline drift');git(sourceRoot,'reset','--hard',head);
  const actual={...source(),base_revision:base,changed_files:fixedLocalGit(sourceRoot,['diff','--no-renames','--name-only','-z',base,head,'--'],{encoding:'utf8'}).split('\0').filter(Boolean).map(path=>({path}))};
  try{assert.throws(()=>api.collectVerificationRetirementCandidates(sourceRoot,options({source:actual})),/OLD_TEST.*BYTES|BASE_CONFIG.*BYTES/);}finally{reset();}
 }
});
test('退休已合入后的新基线若无退休delta，只返回空候选而不强索旧config',()=>{
 needApi();try{
  const base=HEAD;writeFileSync(join(sourceRoot,'after-retirement-marker'),'ordinary later change');const head=commit(sourceRoot);
  const actual={...source(),base_revision:base,head_revision:head,changed_files:[{path:'after-retirement-marker'}]};
  const proof=api.collectVerificationRetirementCandidates(sourceRoot,options({source:actual}));assert.equal(proof.rows.length,0);assert.equal(proof.source.base_revision,base);
 }finally{reset();}
});
test('另五条精确退休独立catalog，不把十阶段常量或复制组件宣称等价覆盖',()=>{
 needApi();try{retireExtra();const proof=api.collectVerificationRetirementCandidates(sourceRoot,options());
  const rows=proof.rows.filter(r=>EXTRA_OLD.includes(r.path));assert.equal(rows.length,5);assert.equal(proof.limitations.length,3);
  for(const row of rows){assert.equal(row.catalog.path,EXTRA_CATALOG);assert.equal(row.entry_verified,false);assert.equal(row.retirement_authorized,false);assert.ok(row.audit.retired.length);assert.ok(row.replacement_inputs.length);}
  const quota=rows.find(r=>r.path.includes('no-quarantine'));assert.equal(quota.base.duplicate_of.sha256,quota.base.sha256);
  const harness=rows.find(r=>r.path.includes('harness-module'));assert.ok(harness.audit.retired.some(s=>s.includes('十阶段')));
  const panorama=rows.find(r=>r.path.endsWith('.tsx'));assert.equal(panorama.replacement_inputs[0].selected_candidate,false);assert.equal(panorama.replacement_inputs[0].requires_selector_reverification,true);
  assert.deepEqual(api.verifyVerificationRetirementCandidates(sourceRoot,{...options(),proof}),proof);
 }finally{reset();}
});
test('额外catalog脏改或提交重算都不能自行批准',()=>{
 needApi();assert.ok(existsSync(join(controlRoot,EXTRA_CATALOG)));const path=join(controlRoot,EXTRA_CATALOG),revision=git(controlRoot,'rev-parse','HEAD');
 try{writeFileSync(path,Buffer.concat([readFileSync(path),Buffer.from('\n')]));assert.throws(()=>api.collectVerificationRetirementCandidates(sourceRoot,options()),/STATE/);commit(controlRoot);assert.throws(()=>api.collectVerificationRetirementCandidates(sourceRoot,options()),/CATALOG/);}finally{git(controlRoot,'reset','--hard',revision);}
});
